import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import styles from './Home.module.css'

export const Home = () => {
  const navigate = useNavigate()
  const buttonRef = useRef(null)
  const [isSticky, setIsSticky] = useState(false)

  useEffect(() => {
    const handleScroll = () => {
      if (!buttonRef.current) return

      const rect = buttonRef.current.getBoundingClientRect()

      // Когда кнопка дошла до верхней части экрана — фиксируем
      if (rect.top <= 20 && !isSticky) {
        setIsSticky(true)
      }

      // Когда пользователь проскроллил вверх — вернуть в поток
      if (window.scrollY < buttonRef.current.offsetTop && isSticky) {
        setIsSticky(false)
      }
    }

    window.addEventListener('scroll', handleScroll)
    return () => {
      window.removeEventListener('scroll', handleScroll)
    }
  }, [isSticky])


  return (
    <div className={styles.container}>
      <div className={styles.logoBlock}>
        <h1 className={styles.logoTextFirst}>FOR</h1>
        <h1 className={styles.logoTextSecond}>WARD</h1>
      </div>
      
      <div className={styles.descriptionBlock}>
        <h3 className={styles.descriptionTitle}>
          МЫ УВАЖАЕМ ВАШЕ ВРЕМЯ<br/> 
          И ГОТОВЫ ВЗЯТЬ НА СЕБЯ<br/> 
          ЧАСТЬ ЗАБОТ<br/> 
          ПО ДИВЕРСИФИКАЦИИ <br/>
          ВАШЕГО ДЕПОЗИТА
        </h3>
        <h3 className={styles.descriptionSubtitle}>
          ТОРГОВЛЯ БУДУЩЕГО. СЕГОДНЯ
        </h3>
      </div>


        <h1 className={styles.logoTextThird}>TRADING</h1>  

    </div>
  )
}
