import React, { useState, useEffect, useRef } from "react";
import { useSelector, useDispatch } from "react-redux";
import { logout } from "../../../redux/slices/loginSlice";
import { Link as ScrollLink } from "react-scroll";
import { Link, useLocation, useNavigate } from "react-router-dom";
import styles from "./DashboardHeader.module.css"

export const DashboardHeader = () => {
  const isAuthenticated = useSelector((state) => state.login.isAuthenticated);
  const user = useSelector((state) => state.login.user)
  const location = useLocation();
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const [scrollTo, setScrollTo] = useState(null);
  /* Список пунктов меню и их свойств. Думаю корректнее перенести на бэкэнд. */
  const menuItemList = [
    /*{
      name: "домой",
      link: "home",
      iconClass: styles.navLink,
      visible: true,
    },*/
    {
      name: "трейды",
      link: "trades",
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: "стратегии",
      link: "strategies",
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: "технологии",
      link: "technologies",
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: "безопасность",
      link: "safety",
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: "начать работу",
      link: "сonnect",
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: "партнерская программа",
      link: "affiliateProgram",
      iconClass: styles.navLink,
      visible: true,
    },
    {/*
      name: "инвестировать",
      link: "/login",
      iconClass: styles.navLink,
      visible: true,
      isExternal: true*/
    },
  ];

  // Показывать кнопку только на определённом маршруте
  const showButton = location.pathname === '/';

  // Обработчик выхода
  const handleLogout = () => {
    if (isAuthenticated) {
      dispatch(logout());
    }
  };

  // Обработчик выбора пункта меню
  const handleMenuItemClick = (sectionId) => {
    if (location.pathname !== "/") {
      setScrollTo(sectionId);
      navigate("/");
    }
  };

  const handleLoginClick = () => {
    navigate('/login')
  }


  const [isSticky, setIsSticky] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsSticky(window.scrollY >= 475);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);



  return (
    <>
    <div className={`${styles.header}`}>
      <div className={`${styles.container}`}>
        <ScrollLink onClick={() => handleMenuItemClick("home")} to={"home"}>
          <div className={styles.companyIdentity}>
            <div className={styles.logo}></div>
            <span className={styles.brandName}>AITrading</span>
          </div>
        </ScrollLink>
        {isAuthenticated ? <div className={styles.userInformation}>
          <div className={styles.userPhoto}>
            <img src="/icon/userPhoto.svg" alt="userPhoto" />
          </div>
          <h3 className={styles.userName}>{user.name}</h3>
        </div> : (
            showButton ? (
              <button className={styles.loginButton} onClick={handleLoginClick}>
                кабинет
              </button>
            ) : null
          )}
      </div>
      <div className={styles.mainMenu}>
                {/* Меню навигации */}
        <nav className={styles.navigation}>

          {menuItemList
            .filter((item) => item.visible)
            .map((item) => {

              return item.isExternal && !user ? (
                <Link
                  className={styles.navLink}
                  key={item.name} // заменить на ID
                  onClick={() => handleMenuItemClick(item.link)}
                  to={item.link}
                >
                  {item.name}
                </Link>
              ) : (
                !user ? (
                <ScrollLink
                  className={styles.navLink}
                  key={item.name} // заменить на ID
                  onClick={() => handleMenuItemClick(item.link)}
                  to={item.link}
                  smooth
                  offset={-130} // Если нужно смещение
                  duration={0} // Более естественная длительность
                >
                  {item.name}
                </ScrollLink>
                ) : null
              );
            })}

          {/* Другие ссылки по мере необходимости */}
        </nav>
        {isAuthenticated ?
        <>
          {/* Кнопка выхода */}
          
          <button className={styles.logoutButton} onClick={handleLogout}>
            выйти
          </button> {/* временное заменю на компонент */} 
        </> : null}
      </div> 
    </div>
      {showButton && (
        <button className={isSticky ? styles.sticky : styles.normal} onClick={handleLoginClick}>
          Инвестировать
        </button>
      )}
      </>
  )
}
