import React, { useEffect, useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { useForm } from "react-hook-form";
import { fetchRegisterRequest, resetRegister } from "../../../redux/slices/registerSlice"
import { Loading } from "../../Loading"
import { DashboardHeader } from "../../headers/DashboardHeader";
import { DashboardFooter } from '../../footers/DashboardFooter';
import { nameValidation, emailValidation, passwordValidation } from '../../../helpers/validationRules';
import { FaEye, FaEyeSlash } from "react-icons/fa";
import "./Register.css"

export default function Register() {
  const { isRegistered, isLoading, errors: error } = useSelector((state) => state.register);
  const [showPassword, setShowPassword] = useState(false);
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const {
    register,
    handleSubmit,
    setError,
    formState: { errors, isSubmitting }
  } = useForm();

  // Если регистрация успешна — редирект
  useEffect(() => {
    if (isRegistered) {
      dispatch(resetRegister());
      navigate("/login");
    }
  }, [isRegistered, navigate, dispatch]);

  // Если сервер вернул ошибки — показать их через setError
  useEffect(() => {
    if (error) {
      Object.entries(error).forEach(([field, messages]) => {
        setError(field, { type: "server", message: messages[0] });
      });
    }
  }, [error, setError]);

  // Отправка формы
  const onSubmit = (data) => {
    dispatch(fetchRegisterRequest(data));
  };

  return (
    <>
    <div className="containerRegister">
      <DashboardHeader />
      {isLoading ? (
        <Loading />
      ) : (
        <div className="register-container">
          <div className="register-card">
            <div className="register-header">
              <h2 className="register-title">Создайте аккаунт</h2>
              <p className="register-subtitle">Заполните данные ниже</p>
            </div>

            <form className="register-form" onSubmit={handleSubmit(onSubmit)}>
              <div className="register-form-group">
                <label htmlFor="name" className="register-form-label">Имя пользователя</label>
                <input
                  type="text"
                  id="name"
                  {...register("name", nameValidation)}
                  className={`register-form-input${errors.name ? " input-error" : ""}`}
                  placeholder="Иван Иванов"
                />
                {errors.name && (
                  <div className='error'>
                    <span className='errorText'>{errors.name.message}</span>
                  </div>
                )}
              </div>

              <div className="register-form-group">
                <label htmlFor="email" className="register-form-label">Электронный адрес</label>
                <input
                  type="email"
                  id="email"
                  {...register("email", emailValidation)}
                  className={`register-form-input${errors.email ? " input-error" : ""}`}
                  placeholder="example@domain.com"
                />
                {errors.email && (
                  <div className='error'>
                    <span className='errorText'>{errors.email.message}</span>
                  </div>
                )}
              </div>

              <div className="register-form-group">
                <label htmlFor="password" className="register-form-label">Пароль</label>
                <div style={{ position: "relative" }}>
                  <input
                    type={showPassword ? "text" : "password"}
                    id="password"
                    {...register("password", passwordValidation)}
                    className={`register-form-input${errors.password ? " input-error" : ""}`}
                    placeholder="••••••••"
                    autoComplete="new-password"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword((prev) => !prev)}
                    style={{
                      position: "absolute",
                      right: 10,
                      top: "50%",
                      transform: "translateY(-50%)",
                      background: "none",
                      border: "none",
                      cursor: "pointer",
                      padding: 0,
                      color: "#888"
                    }}
                    tabIndex={-1}
                    aria-label={showPassword ? "Скрыть пароль" : "Показать пароль"}
                  >
                    {showPassword ? <FaEyeSlash size={20} /> : <FaEye size={20} />}
                  </button>
                </div>
                {errors.password && (
                  <div className='error'>
                    <small className='errorText'>{errors.password.message}</small>
                  </div>
                )}
              </div>

              {isSubmitting ? (
                <div className="spinner">Загрузка...</div>
              ) : (
                <button type="submit" className="register-button">
                  Зарегистрироваться
                </button>
              )}

              <p className="login-link">
                Уже есть аккаунт? <Link to="/login">Войдите</Link>
              </p>
            </form>
          </div>
        </div>
      )}
      <DashboardFooter />
    </div>
    </>
  );
}