// sagas/userDataSaga.js
import { call, put, takeEvery } from "redux-saga/effects";
import { fetchUserDataApi } from "../../api/authApi";
import {
  fetchUserDataRequest,
  fetchUserDataSuccess,
  fetchUserDataFailure,
  saveAccountNumberRequest,
  saveAccountNumberSuccess,
  saveAccountNumberFailure,
  autoTrackingRequest,
  autoTrackingSuccess,
  autoTrackingFailure,
} from "../slices/userDataSlice";

import { saveAccountNumberApi } from "../../api/authApi";
import { saveAutoTrackingApi } from '../../api/authApi';


function* fetchUserDataSaga(action) {
  try {
    const userId = action.payload;

    const { data, status } = yield call(fetchUserDataApi, userId);

    switch (status) {
      case 200:
        yield put(fetchUserDataSuccess(data));
        break;

      case 404:
        yield put(fetchUserDataFailure("Пользователь не найден"));
        break;

      case 401:
        yield put(fetchUserDataFailure("Не авторизован"));
        break;

      default:
        yield put(fetchUserDataFailure(data.message || "Неизвестная ошибка"));
    }
  } catch (error) {
    yield put(fetchUserDataFailure("Ошибка соединения с сервером"));
    console.error("Ошибка получения данных пользователя:", error);
  }
}

function* saveAccountNumberSaga(action) {
  try {
    const { userId, accountNumber, accountType } = action.payload;

    const { data, status } = yield call(saveAccountNumberApi, { userId, accountNumber, accountType });

    if (status === 200) {
      yield put(saveAccountNumberSuccess(data));
    } else {
      yield put(saveAccountNumberFailure(data.message || "Ошибка сохранения"));
    }
  } catch (error) {
    yield put(saveAccountNumberFailure("Ошибка соединения с сервером"));
    console.error("Ошибка сохранения номера аккаунта:", error);
  }
}

function* autoTrackingSaga(action) {
  try {
    const { userId, autofollow } = action.payload;

    const { data, status } = yield call(saveAutoTrackingApi, { userId, autofollow });

    if (status === 200) {
      yield put(autoTrackingSuccess(data));
    } else {
      yield put(autoTrackingFailure(data.message || 'Ошибка включения автоследования'));
    }
  } catch (error) {
    yield put(autoTrackingFailure('Ошибка соединения с сервером'));
    console.error('Ошибка автоследования:', error);
  }
}

export function* watchUserDataSaga() {
  yield takeEvery(fetchUserDataRequest.type, fetchUserDataSaga);
  yield takeEvery(saveAccountNumberRequest.type, saveAccountNumberSaga);
  yield takeEvery(autoTrackingRequest.type, autoTrackingSaga);
}