import { call, put, takeEvery } from "redux-saga/effects";
import { fetchLoginApi } from "../../api/authApi";
import {
  fetchLoginRequest,
  fetchLoginSuccess,
  fetchLoginFailure,
} from "../slices/loginSlice";

export function* fetchLoginSaga(action) {
  try {
    const { data, status } = yield call(fetchLoginApi, action.payload);
    
    switch (status) {
      case 200:
        //localStorage.setItem("token", data.token);
        yield put(fetchLoginSuccess({ user: data.user, token: data.token }));
        break;
        
      case 401:
        yield put(fetchLoginFailure("Неверные учетные данные"));
        break;
        
      case 403:
        yield put(fetchLoginFailure("Доступ запрещен"));
        break;
        
      default:
        yield put(fetchLoginFailure(data.message || "Неизвестная ошибка"));
    }
  } catch (error) {
    yield put(fetchLoginFailure("Ошибка подключения к серверу"));
    console.error("Сетевая ошибка:", error);
  }
}

export function* watchLoginSaga() {
  yield takeEvery(fetchLoginRequest.type, fetchLoginSaga);
}
