import { call, put, takeEvery } from "redux-saga/effects";
import { fetchRegisterApi } from "../../api/authApi"
import {
  fetchRegisterRequest,
  fetchRegisterSuccess,
  fetchRegisterFailure,
} from "../slices/registerSlice";
import { toast, Bounce } from "react-toastify";

/* Saga для регистрации */
export function* fetchRegisterSaga(action) {
  try {
    const { data, status } = yield call(fetchRegisterApi, action.payload);

    switch (status) {
      case 201:
        yield put(fetchRegisterSuccess(data));
        toast("Пользователь зарегистрирован успешно", {
          position: "top-right",
          type: "success",
          autoClose: 5000,
          hideProgressBar: false,
          closeOnClick: true,
          pauseOnHover: true,
          draggable: true,
          progress: undefined,
          theme: "light",
          transition: Bounce,
        });
        break;

      case 400:
        yield put(fetchRegisterFailure("Некорректные данные"));
        break;

      case 403:
        yield put(fetchRegisterFailure("Доступ запрещен"));
        break;

      default:
        yield put(fetchRegisterFailure(data.message || "Неизвестная ошибка"));
        break;
    }
  } catch (error) {
    yield put(fetchRegisterFailure("Ошибка подключения к серверу"));
    console.error("Сетевая ошибка:", error);
  }
}

export function* watchRegisterSaga() {
  yield takeEvery(fetchRegisterRequest.type, fetchRegisterSaga);
}